// Uma conta por banco/pessoa — usamos o accountId para descobrir o itemId de cada conexão
// O itemId é o que a Pluggy usa para buscar investimentos
const contas = [
  // Ariane
  { accountId: "5eb1c057-af54-49f0-8f28-32b906f65cd7", dono: "Ariane",  banco: "Nubank" },
  { accountId: "a98c9617-7e39-4356-8fa9-010e467b95e8", dono: "Ariane",  banco: "Santander" },
  // Matheus
  { accountId: "bf968b42-9cd7-47cd-aab1-77bbd4fe04fb", dono: "Matheus", banco: "Nubank" },
  { accountId: "db9e68d5-ec6b-4da0-b4b7-b957ebe9f3e6", dono: "Matheus", banco: "Santander" },
  { accountId: "0b59cc94-f351-4e59-9f6f-ac921c488155", dono: "Matheus", banco: "Bradesco" },
  { accountId: "77721586-135e-4d20-af6c-e85bde1046e1", dono: "Matheus", banco: "Inter" },
  { accountId: "b638bc7d-2fec-4443-98d8-91b31b1f56c9", dono: "Matheus", banco: "Itau" }
];

return contas.map(c => ({ json: c }));

// Recupera o itemId de cada conta e monta a lista de items únicos
// Dois accountIds do mesmo banco/pessoa retornam o MESMO itemId — deduplicamos aqui
const mapaAccountMeta = {
  "5eb1c057-af54-49f0-8f28-32b906f65cd7": { dono: "Ariane",  banco: "Nubank" },
  "a98c9617-7e39-4356-8fa9-010e467b95e8": { dono: "Ariane",  banco: "Santander" },
  "bf968b42-9cd7-47cd-aab1-77bbd4fe04fb": { dono: "Matheus", banco: "Nubank" },
  "db9e68d5-ec6b-4da0-b4b7-b957ebe9f3e6": { dono: "Matheus", banco: "Santander" },
  "0b59cc94-f351-4e59-9f6f-ac921c488155": { dono: "Matheus", banco: "Bradesco" },
  "77721586-135e-4d20-af6c-e85bde1046e1": { dono: "Matheus", banco: "Inter" },
  "b638bc7d-2fec-4443-98d8-91b31b1f56c9": { dono: "Matheus", banco: "Itau" }
};

const vistos = new Set();
const itemsUnicos = [];

$input.all().forEach(item => {
  const account = item.json;
  const itemId  = account.itemId;
  const meta    = mapaAccountMeta[account.id] || { dono: 'Desconhecido', banco: 'Desconhecido' };

  if (itemId && !vistos.has(itemId)) {
    vistos.add(itemId);
    itemsUnicos.push({ json: { itemId, dono: meta.dono, banco: meta.banco } });
  }
});

return itemsUnicos.length > 0 ? itemsUnicos : [{ json: { skip: true } }];

// Recupera o mapeamento itemId -> dono/banco do nó anterior
const listaItems = $('Montar Lista de Items').all();
const mapaItemDono = {};
listaItems.forEach(item => {
  if (item.json.itemId) mapaItemDono[item.json.itemId] = { dono: item.json.dono, banco: item.json.banco };
});

const investimentos = [];
$input.all().forEach(item => {
  const resultados = item.json.results || [];
  resultados.forEach(inv => {
    if (!inv.id) return;
    const meta = mapaItemDono[inv.itemId] || { dono: 'Desconhecido', banco: 'Desconhecido' };

    // valor atual: balance; se faltar, preço unitário * quantidade (NUNCA o preço unitário puro)
    const valorAtual = (inv.balance != null) ? inv.balance : ((inv.value || 0) * (inv.quantity || 0));
    // principal aplicado: amountOriginal; senão amount; senão o valor atual
    const valorInvestido = (inv.amountOriginal != null) ? inv.amountOriginal
                          : ((inv.amount != null) ? inv.amount : valorAtual);
    // lucro: SÓ o que a Pluggy informa. Se não vier, 0 (nunca calcular via value-amount)
    const lucro = (inv.amountProfit != null) ? inv.amountProfit : 0;

    investimentos.push({
      json: {
        id_investimento:     inv.id,
        item_id:             inv.itemId,
        nome:                inv.name         || 'Sem nome',
        tipo:                inv.type          || 'Desconhecido',
        subtipo:             inv.subtype       || null,
        valor_investido:     valorInvestido,
        valor_atual:         valorAtual,
        lucro_acumulado:     lucro,
        quantidade:          inv.quantity      || null,
        rentabilidade_anual: inv.annualRate    || null,
        data_vencimento:     inv.date ? inv.date.split('T')[0] : null,
        banco:               meta.banco,
        responsavel:         meta.dono,
        status:              inv.status        || null,
        atualizado_em:       new Date().toISOString()
      }
    });
  });
});

return investimentos.length > 0 ? investimentos : [{ json: { skip: true } }];
